{
  "case_id": "xsu_sg_013_specialist_declaration",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Kernen er rigtig (i særlige tilfælde, når art og grad ikke er tilstrækkeligt beskrevet). Svaret har dog væsentlige fejl. Det vender logikken om: 'Hvis dokumentationen allerede beskriver dette klart nok, peger det imod behov for speciallægeerklæring; hvis ikke, peger det for…' er forkert formuleret. Det siger også, at UDK 'kun kan kræve' erklæringen, når dokumentationen er 'for uklar', hvilket gør beskrivelsen til en udtømmende betingelse. Kilden bruger 'anmode', ikke 'kræve', og opremser eksempler. De fire eksempelgrupper nævnes slet ikke."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element er dækket. Det andet er ikke: ingen af de fire eksempelgrupper (symptomintensitet/hyppighed, uoverensstemmelse, tvivl om behandling/prognose, daglig funktion vs. ferie) nævnes. Betalingen af udgifter er heller ikke nævnt, men det er kun et supplerende element."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret forholder sig direkte til, hvornår UDK kan bede om en speciallægeerklæring, og angiver hovedbetingelsen. Det mangler eksemplerne, men besvarer spørgsmålet i overordnede træk uden irrelevant udenomssnak."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret nummererer henvisninger og angiver vejledning nr. 10157 af 5. oktober 2026 som kilde. Det er en identificerbar kilde, selv om afsnitsnummeret ikke er angivet."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning nr. 10157 af 5/10/2026 findes i det frosne materiale og er aktuel og autoritativ. Afsnit 5.1.3.2 er netop den relevante passage."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Den centrale påstand om 'i særlige tilfælde' og utilstrækkelig beskrivelse understøttes af afsnit 5.1.3.2. Påstanden om, at UDK 'kun kan kræve' erklæringen, når dokumentationen er for uklar, støttes ikke af passagen, som bruger 'anmode' og angiver eksempler. Det samme gælder den omvendte sætning om, at klar dokumentation 'peger imod' behov. Udsagnet om, at speciallægeerklæring er en af flere former for yderligere oplysninger, er heller ikke dækket af passagen. Det samme gælder, at vejledningen handler om 'hvilken dokumentation der er nødvendig'."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en retsvirkning uden støtte: UDK 'kan kræve' erklæringen, og kun når dokumentationen er 'for uklar'. Det hævder desuden, at speciallægeerklæring er én blandt flere former for yderligere lægefaglige oplysninger, og at vejledningen angiver en 'retningslinje' om dette. Den formelle bestemmelse i § 37, stk. 5 om yderligere dokumentation er ikke nævnt."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "'I særlige tilfælde' og 'ikke automatisk' er bevaret. Det kræves dog også, at eksemplerne gengives som illustrative og alternative med 'stor tvivl', og de mangler helt. Ordet 'kun' gør desuden betingelsen udtømmende i stedet for illustrativ."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Afsnittet 'Nærmere afgrænsning' er selvmodsigende: 'Hvis dokumentationen allerede beskriver dette klart nok, peger det imod behov for speciallægeerklæring' er forkert i forhold til sammenhængen. Svaret understreger, at kravet ikke er automatisk, men konkluderer så, at UDK 'kun kan kræve' erklæringen i bestemte tilfælde."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Kilden bruger 'kan anmode' i særlige tilfælde. Svaret skifter til 'kun kan kræve', som er mere absolut og ændrer modaliteten fra anmodning til krav. Det gør også eksemplerne til en udtømmende betingelse."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret dækker hovedreglen: kan i særlige tilfælde anmode, når dokumentationen ikke i tilstrækkelig grad beskriver art og grad. Det udelader alle fire 'f.eks.'-eksempler og skriver 'kun kræve' i stedet for 'anmode'."
    }
  },
  "overall_notes": "Svaret får hovedreglen rigtig, men udelader de fire eksempelgrupper, som rubrikken kræver. Det formulerer desuden betingelsen mere snævert og absolut ('kun kan kræve') og indeholder en logisk fejl i afsnittet om afgrænsning. Kildehenvisningen er identificerbar og gyldig, men understøtter ikke alle påstande."
}

